public class Ticket
{
    private String seat;
    private int price;
    public Ticket(String seat, int price)
    {
        this.seat = seat;
        this.price = price;
    }
    public String getSeat()
    {
        return seat;
    }
    public int getPrice()
    {
        return price;
    }
}

public class StudentTicket extends Ticket
{
    private String studentId;
    public StudentTicket(String seat, int price,
        String studentId)
    {
        super(seat, price);
        this.studentId = studentId;
    }
    public String getStudentId()
    {
        return studentId;
    }
    public int getDiscount()
    {
        return getPrice() / 5;
    }
    public void printTicket()
    {
        System.out.println("Seat " + getSeat() + ": " + getPrice() + " dollars, student "
            + studentId);
        System.out.println("  discount: " + getDiscount() + " dollars");
    }
}
